    "cdc_statistic": "0.3% (or 1 in 300)",
    "factors": ["rapid degradation of HIV outside the human body", "small volume of blood typically involved", "effectiveness of post-exposure prophylaxis (PEP) if administered promptly"],
    "pep": {
      "description": "involves taking antiretroviral drugs within 72 hours of exposure to prevent HIV infection",
      "timeframe": "within 72 hours"
